/bin/bash -lc "python - <<'PY'
import urllib.request,json
for t in ['Experiment','Series','Biosample','Donor']:
 url=f'https://www.encodeproject.org/search/?type={t}&searchTerm=AFGR&format=json&limit=5'
 req=urllib.request.Request(url, headers={'Accept':'application/json','User-Agent':'Mozilla/5.0'})
 try:
  data=json.load(urllib.request.urlopen(req,timeout=30))
  print('\\n',t,'total',data.get('total'))
  for g in data.get('@graph',[])[:5]: print(g.get('@id'), g.get('accession'), g.get('assay_title'), g.get('description'), g.get('title'), g.get('status'))
 except Exception as e: print(t,e)
PY"

